      p_21484_.putBoolean("CanPickUpLoot", this.canPickUpLoot());
      p_21484_.putBoolean("PersistenceRequired", this.persistenceRequired);
      ListTag listtag = new ListTag();

      for(ItemStack itemstack : this.armorItems) {
