      if (!itemstack1.isEmpty()) {
         this.onItemPickup(p_21471_);
         this.take(p_21471_, itemstack1.getCount());
         itemstack.shrink(itemstack1.getCount());
         if (itemstack.isEmpty()) {
            p_21471_.discard();
         }
